    private fun normalized(value: String): String = value.trim().trim('"').trim()

    private fun parsedSection(raw: String): Pair<String, String> {
        val source = normalized(raw)
        val section = source.substringBefore('/').trim()
        val suffix = source.substringAfter('/', "").uppercase()
        val upper = source.uppercase()
        val type = when {
            upper.startsWith("ЦБ") || suffix.contains("ЦБ") -> "банкомат"
            upper.startsWith("Ц") || suffix.contains("Ц") -> "цоколь"
            upper.startsWith("П") || suffix.contains("П") -> "паркинг"
            upper.startsWith("С") || suffix.contains("С") -> "склады"
            suffix.contains("О") -> "офис"
            else -> ""
        }
        val floor = Regex("^(\\d+)-").find(section)?.groupValues?.get(1)
        return section to listOfNotNull(floor?.let { "$it этаж" }, type.takeIf { it.isNotBlank() }).joinToString(", ")
    }

    val all: List<TenantRecord> = rows.map { row ->
        val (section, floorOrType) = parsedSection(row.getOrElse(0) { "" })
        TenantRecord(section, floorOrType, normalized(row.getOrElse(1) { "" }), normalized(row.getOrElse(2) { "" }), normalized(row.getOrElse(3) { "" }), normalized(row.getOrElse(4) { "" }), normalized(row.getOrElse(5) { "" }), normalized(row.getOrElse(6) { "" }), normalized(row.getOrElse(7) { "" }))
    }
}
